import React, { useCallback, useEffect, useState } from "react";
import { api, todayISO, fmtDate } from "../api";
import { Stat } from "../components";

export default function Today({ isAdmin = true }) {
  const [d, setD] = useState(todayISO());
  const [emps, setEmps] = useState([]);
  const [day, setDay] = useState(null);
  const [msg, setMsg] = useState("");
  const [err, setErr] = useState("");
  const [q, setQ] = useState("");

  const load = useCallback(async () => {
    try {
      const [e, a] = await Promise.all([api("/employees"), api(`/attendance/day?d=${d}`)]);
      setEmps(e.filter((x) => x.active));
      setDay(a);
    } catch (x) { setErr(x.message); }
  }, [d]);
  useEffect(() => { load(); }, [load]);
  useEffect(() => { const t = setInterval(load, 20000); return () => clearInterval(t); }, [load]);

  const flash = (m) => { setMsg(m); setTimeout(() => setMsg(""), 3500); };
  const mark = async (empId, status) => {
    setErr("");
    const cur = day.records[empId]?.status;
    const next = cur === status ? "" : status;
    try {
      await api("/attendance", { method: "PUT", body: { employee_id: empId, date: d, status: next } });
      load();
    } catch (x) { setErr(x.message); }
  };
  const allPresent = async () => {
    const r = await api("/attendance/bulk", { method: "POST", body: { date: d, status: "P", only_empty: true } });
    flash(`${r.changed} employee(s) marked Present`);
    load();
  };
  const sendNow = async () => { await api("/notifications/flush", { method: "POST" }); flash("Pending WhatsApp messages sent"); load(); };
  const ownerSummary = async () => {
    try { const r = await api("/summary/send", { method: "POST", body: { date: d } }); flash(`Summary sent to ${r.length} owner number(s)`); }
    catch (x) { setErr(x.message); }
  };

  if (!day) return <div className="muted pad">{err || "Loading…"}</div>;
  const recs = day.records;
  const cnt = (s) => emps.filter((e) => recs[e.id]?.status === s).length;
  const unmarked = emps.filter((e) => !recs[e.id]).length;
  const isSunday = new Date(d + "T00:00").getDay() === 0;
  const shown = emps.filter((e) => (e.name + e.code).toLowerCase().includes(q.toLowerCase()));

  return (
    <div>
      <div className="toolbar">
        <div className="row-inline">
          <input type="date" value={d} onChange={(e) => e.target.value && setD(e.target.value)} />
          <b>{fmtDate(d)}</b>{isSunday && <span className="tag muted-tag">Sunday</span>}
        </div>
        <div className="row-inline">
          <button className="btn" onClick={allPresent}>Mark unmarked as Present</button>
          <button className="btn" onClick={sendNow}>Send pending messages now</button>
          {isAdmin && <button className="btn primary" onClick={ownerSummary}>Send owner summary</button>}
        </div>
      </div>
      {msg && <div className="okmsg">{msg}</div>}
      {err && <div className="error">{err}</div>}
      <div className="stats">
        <Stat label="Employees" value={emps.length} />
        <Stat label="Present" value={cnt("P")} tone="green" />
        <Stat label="Half day" value={cnt("H")} tone="amber" />
        <Stat label="Absent" value={cnt("A")} tone="red" />
        <Stat label="Not marked" value={unmarked} />
      </div>
      <p className="muted small">Each employee gets a WhatsApp message about a minute after you mark them, so a quick correction only sends the final status. Messages go out for today and yesterday only.</p>
      <div className="card flush">
        <div className="pad-sm"><input placeholder="Search…" value={q} onChange={(e) => setQ(e.target.value)} /></div>
        <table className="grid-table today">
          <tbody>
            {shown.map((e) => {
              const r = recs[e.id];
              const pending = day.pending.includes(e.id);
              return (
                <tr key={e.id}>
                  <td className="t-name"><b>{e.name}</b><div className="muted small">{[e.designation, e.phone || "no phone"].filter(Boolean).join(" · ")}</div></td>
                  <td className="r nowrap t-btns">
                    {["P", "H", "A"].map((s) => (
                      <button key={s} className={"mark " + s + (r?.status === s ? " on" : "")} onClick={() => mark(e.id, s)}>
                        {s === "P" ? "Present" : s === "H" ? "Half day" : "Absent"}
                      </button>
                    ))}
                  </td>
                  <td className="wa-col small">
                    {r && (pending ? <span className="muted">⏳ sending soon</span> : r.notified ? <span className="ok-text">✓ WhatsApp sent</span> : <span className="muted">not sent</span>)}
                  </td>
                </tr>
              );
            })}
            {!shown.length && <tr><td className="muted pad">No active employees.</td></tr>}
          </tbody>
        </table>
      </div>
    </div>
  );
}
